import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Handl SDK Generator — Windows and macOS C Backend Support","description":"","frontmatter":{"title":"Handl SDK Generator — Windows and macOS C Backend Support","type":"adr","date":"2026-10-28T00:00:00.000Z","status":"proposed","status_note":"Proposed."},"headers":[],"relativePath":"c/project/adrs/0110-handl-sdkgen-windows-macos.md","filePath":"vendored/c/project/adrs/0110-handl-sdkgen-windows-macos.md"}`),a={name:`c/project/adrs/0110-handl-sdkgen-windows-macos.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0110-handl-sdk-generator-—-windows-and-macos-c-backend-support" tabindex="-1">ADR-0110: Handl SDK Generator — Windows and macOS C Backend Support <a class="header-anchor" href="#adr-0110-handl-sdk-generator-—-windows-and-macos-c-backend-support" aria-label="Permalink to “ADR-0110: Handl SDK Generator — Windows and macOS C Backend Support”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><a href="./0107-handl-sdk-generator.html">ADR-0107 — Handl SDK Generator</a> introduced the <code>plugin-sdkgen-backend-c</code> C / libclang backend and deliberately scoped the first concrete implementation to Linux x86_64. Windows and macOS support were left for a later phase because each target requires distinct system-include paths, shared-library naming, and ABI conventions.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Windows and macOS support will be implemented in the existing <code>plugin-sdkgen-backend-c</code> crate by making target-specific behavior data-driven, not by adding new backends.</p><ul><li>Add target-aware include / sysroot lookup: <ul><li>Linux: <code>-I/usr/include</code> and the libclang resource directory.</li><li>macOS: the macOS SDK path (<code>xcrun --show-sdk-path</code> or <code>SDKROOT</code>) and <code>-isysroot</code>.</li><li>Windows: the MSVC / Clang system include set and Windows-style paths.</li></ul></li><li>Map the target triple to the correct shared-object name at emitter time: <ul><li><code>libc.so.6</code> for Linux glibc.</li><li><code>libSystem.dylib</code> for macOS.</li><li><code>*.dll</code> for Windows.</li></ul></li><li>Allow the user to pass an explicit target triple (<code>--target x86_64-pc-windows-msvc</code>, <code>--target aarch64-apple-darwin</code>, etc.) and validate it during backend construction.</li><li>Preserve the existing port / adapter split and the <code>SdkgenModule</code> IR; only the parser options and the shared-library name in the adapter change per target.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>The C backend becomes genuinely multi-platform without a new crate per OS.</li><li><code>.sdkgen.yaml</code> gains a <code>target</code> / <code>library</code> section so the shared-object mapping is user-overridable.</li><li>Tests must run on CI for each supported target, or via golden snapshots per target.</li><li>Linux remains the default and best-supported target.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li><a href="./0107-handl-sdk-generator.html">ADR-0107 — Handl SDK Generator</a></li><li><code>crates/plugin-sdkgen-backend-c</code></li></ul>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};